        "a scanning program must carry the engine"
    );
    assert!(
        !user_asm(
            r#"<?php $h = fopen("/dev/null", "r"); echo sprintf("%d", strlen("abc")); fgets($h);"#
        )
        .contains("__elephc_scanf"),
        "sprintf/strlen/fgets must not pull the scanf engine in"
    );
